  "named": [],
  "about_items": [
    {
      "n": "#147·19",
      "text": "A chocolate satin maxi dress in a relaxed, draped silhouette that flows from the bust to just above the ankles, with delicate thin straps and a soft sheen."
    },
    {
      "n": "#253·29",
      "text": "A grey tweed blazer designed with an asymmetrical one-shoulder neckline, long sleeves, a double-breasted front, and a peplum hem that sits at the waist."
    },
    {
      "n": "#177·41",
      "text": "A structured crossbody bag featuring a colorful geometric tapestry panel atop a solid sand-colored base, with an adjustable strap for easy wear."
    },
    {
      "n": "#128·34",
      "text": "A silk scarf printed with an intricate blue and white floral and bird motif on a crisp background."
    },
    {
      "n": "#173·25",
      "text": "Stud earrings set with polished square-cut green malachite stones, each encased in a smooth gold-tone metal frame."
    },
    {
      "n": "#156·34",
      "text": "A glossy pink rectangular hair clip or accessory featuring the word 'CELINE' in white letters, designed to add a pop of color and brand identity."
    },
    {
      "n": "#285·06",
      "text": "Tall beige suede boots with a sleek straight shaft and a low kitten heel, finished with a pointed toe for a modern touch."
    },
    {
      "n": "#32·04",
      "text": "A long grey wool coat with a double-breasted front, wide lapels, four-button closure, and an English-style collar for structured elegance."
    }
  ]
}
